evidence.powershell_avir_command_definition:
$env:AVIR_DISABLE_NONESSENTIAL_TRAFFIC = "1"
    $env:AVIR_DISABLE_BACKGROUND_TASKS = "1"
    $env:AVIR_EXPERIMENTAL_AGENT_TEAMS = "1"
    try {
        & "<local-path>" @args
    } finally {
        Remove-Item Env:\AVIR_DISABLE_NONESSENTIAL_TRAFFIC -ErrorAction SilentlyContinue
        Remove-Item Env:\AVIR_DISABLE_BACKGROUND_TASKS -ErrorAction SilentlyContinue
        Remove-Item Env:\AVIR_EXPERIMENTAL_AGENT_TEAMS -ErrorAction SilentlyContinue
    }
